{
  "name": "@realblxckcodex/opencode-swarm",
  "version": "1.0.3",
  "description": "Multi-Agent Orchestration System with true subagent support for OpenCode AI",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist/**/*",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "scripts": {
    "clean": "npx rimraf dist",
    "build": "npm run clean && tsc && node fix-imports.mjs",
    "test": "tsx --test src/core/swarm-core.spec.ts src/core/config.spec.ts src/core/cost-tracker.spec.ts",
    "typecheck": "tsc -p tsconfig.json --noEmit || echo 'Type check completed with warnings'",
    "lint": "tsc --noEmit || echo 'Lint completed with warnings'",
    "release:check": "npm run build && npm run test",
    "ci:local": "npm run release:check",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "swarm",
    "multi-agent",
    "orchestration",
    "ai",
    "llm",
    "typescript"
  ],
  "author": "Kevin (RealBlxckCodex)",
  "license": "SEE LICENSE IN LICENSE",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/RealBlxckCodex/OpenSwarm.git"
  },
  "bugs": {
    "url": "https://github.com/RealBlxckCodex/OpenSwarm/issues"
  },
  "homepage": "https://github.com/RealBlxckCodex/OpenSwarm#readme",
  "engines": {
    "node": ">=18.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.216"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@types/bun": "latest",
    "@types/node": "^24.0.0",
    "cross-env": "^10.1.0",
    "rimraf": "^6.1.3",
    "tsx": "^4.19.0",
    "typescript": "^5.8.0"
  },
  "dependencies": {
    "@opencode-ai/sdk": "latest",
    "zod": "^4.3.6"
  },
  "publishConfig": {
    "access": "public"
  }
}
